	"period_start" date,
	"as_of" date NOT NULL,
	"currency" text DEFAULT 'USD' NOT NULL,
	"a_opening" numeric(14, 4),
	"a_closing" numeric(14, 4) NOT NULL,
	"b_opening" numeric(14, 4),
	"b_closing" numeric(14, 4) NOT NULL,
	"difference" numeric(14, 4) NOT NULL,
	"residual" numeric(14, 4) NOT NULL,
	"outcome" text NOT NULL,
	"status" text DEFAULT 'open' NOT NULL,
	"settings" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"carried_from_id" uuid,
	"sources" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"agent_version_id" uuid,
	"run_id" uuid,
	"signed_off_by" uuid,
	"signed_off_at" timestamp with time zone,
	"note" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "reconciliation_id_tenant_key" UNIQUE("id","tenant_id"),
	CONSTRAINT "reconciliation_status_check" CHECK ("reconciliation"."status" in ('open', 'signed_off', 'superseded')),
	CONSTRAINT "reconciliation_outcome_check" CHECK ("reconciliation"."outcome" in ('balanced', 'explained', 'unexplained')),
	CONSTRAINT "reconciliation_signed_off_check" CHECK (("reconciliation"."status" = 'signed_off') = ("reconciliation"."signed_off_by" is not null and "reconciliation"."signed_off_at" is not null)),
	CONSTRAINT "reconciliation_sign_off_explained_check" CHECK ("reconciliation"."status" <> 'signed_off' or "reconciliation"."residual" = 0)
);
